(6080411, 895484, 49954, '<td valign="top">PP halo effect is too distracting...  Could have been better done.  Great look and subject</td>', 'PP halo effect is too distracting...  Could have been better done.  Great look and subject', '2010-07-05 01:25:10.000000', NULL, 1),
