(6080606, 895569, 5822, '<td valign="top">I love how the fullness of her hair mirror the fullness of the bunch of flowers. The lavender she''s holding is a bit too dark.</td>', 'I love how the fullness of her hair mirror the fullness of the bunch of flowers. The lavender she''s holding is a bit too dark.', '2010-07-05 03:41:26.000000', NULL, 1),
(6080608, 895508, 5822, '<td valign="top">Those eyes (or lack of them) and skin tones are haunting. Nice colors and bokeh too.</td>', 'Those eyes (or lack of them) and skin tones are haunting. Nice colors and bokeh too.', '2010-07-05 03:44:22.000000', NULL, 1),
