(6081514, 895670, 115814, '<td valign="top">Comment only from a non-voting, non-member: Hmm... What would four men (complete strangers to the photograhper) be doing in this location, dressed as they are? Whatever the answer, this photo is intriguing, but I can''t really decide if the overall dark tone detracts from the whole effect...</td>', 'Comment only from a non-voting, non-member: Hmm... What would four men (complete strangers to the photograhper) be doing in this location, dressed as they are? Whatever the answer, this photo is intriguing, but I can''t really decide if the overall dark tone detracts from the whole effect...', '2010-07-05 20:22:47.000000', NULL, 1),
(6081685, 895403, 37845, '<td valign="top">This shot just oozes <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=14386" rel="nofollow" target="_blank">librodo</a>''s style</td>', 'This shot just oozes  librodo''s style', '2010-07-05 23:45:31.000000', NULL, 1),
