(6082327, 895539, 114225, '<td valign="top">Good pose for the subject. Good lighting and depth of field. If possible, it would have been nice to have him take the camera off his shoulder.</td>', 'Good pose for the subject. Good lighting and depth of field. If possible, it would have been nice to have him take the camera off his shoulder.', '2010-07-06 14:53:48.000000', NULL, 1),
(6082328, 895435, 114225, '<td valign="top">Great shot. Well composed with just the hand hold the ice cream, and the joy on the subject''s face is good to see.</td>', 'Great shot. Well composed with just the hand hold the ice cream, and the joy on the subject''s face is good to see.', '2010-07-06 14:54:37.000000', NULL, 1),
