(6082823, 895519, 115814, '<td valign="top">Comment only from a non-voting, non-member: Whoa. If that look is in response to an unexpected candid photo, I''m glad it wasn''t me on the other end of the lens!</td>', 'Comment only from a non-voting, non-member: Whoa. If that look is in response to an unexpected candid photo, I''m glad it wasn''t me on the other end of the lens!', '2010-07-06 23:21:44.000000', NULL, 1),
(6082825, 894726, 115814, '<td valign="top">Comment only from a non-voting, non-member: Looks like a distant relative of George Carlin. An interesting capture with a color tonal range that emphasized the bleakness of the subject.</td>', 'Comment only from a non-voting, non-member: Looks like a distant relative of George Carlin. An interesting capture with a color tonal range that emphasized the bleakness of the subject.', '2010-07-06 23:21:54.000000', NULL, 1),
(6082831, 895681, 115814, '<td valign="top">Comment only from a non-voting, non-member: An interesting rule breaker... having the subject leaving the frame. In my humble, amateur opinion, the composition is effective, but I would have liked to see the face be out of the shadows or at least brightened a bit.</td>', 'Comment only from a non-voting, non-member: An interesting rule breaker... having the subject leaving the frame. In my humble, amateur opinion, the composition is effective, but I would have liked to see the face be out of the shadows or at least brightened a bit.', '2010-07-06 23:24:26.000000', NULL, 1),
(6082838, 895680, 115814, '<td valign="top">Comment only from a non-voting, non-member: In my humble, amateur opinion, this is a compelling image. Not sure it''s street portraiture, but it''s nicely done. I especially like the effect of the framing created by the diagonal blue jeans on the lower left mirrored by the diagonal line of the light on the top right. This diagonal border is nicely complemented by the line of the necklace flowing from lower left to upper right. Nice!</td>', 'Comment only from a non-voting, non-member: In my humble, amateur opinion, this is a compelling image. Not sure it''s street portraiture, but it''s nicely done. I especially like the effect of the framing created by the diagonal blue jeans on the lower left mirrored by the diagonal line of the light on the top right. This diagonal border is nicely complemented by the line of the necklace flowing from lower left to upper right. Nice!', '2010-07-06 23:27:40.000000', NULL, 1),
(6082840, 895569, 115814, '<td valign="top">Comment only from a non-voting, non-member: Wow that''s a lot of purple. I wish the eyes were not lost in shadow. Can''t help wonder what color they are....</td>', 'Comment only from a non-voting, non-member: Wow that''s a lot of purple. I wish the eyes were not lost in shadow. Can''t help wonder what color they are....', '2010-07-06 23:29:00.000000', NULL, 1),
(6082841, 895633, 115814, '<td valign="top">Comment only from a non-voting, non-member: As if the image of the scarred tough guy with the ice cream cone isn''t enough irony... it''s purple and pink ice cream. Cool.</td>', 'Comment only from a non-voting, non-member: As if the image of the scarred tough guy with the ice cream cone isn''t enough irony... it''s purple and pink ice cream. Cool.', '2010-07-06 23:29:10.000000', NULL, 1),
(6082845, 895677, 115814, '<td valign="top">Comment only from a non-voting, non-member: While the relative placement of the person and the dog is interesting, the juxtaposition of the dog with the background rock distracts too much and becomes the unintended focus of attention.</td>', 'Comment only from a non-voting, non-member: While the relative placement of the person and the dog is interesting, the juxtaposition of the dog with the background rock distracts too much and becomes the unintended focus of attention.', '2010-07-06 23:31:48.000000', NULL, 1),
(6082847, 895236, 115814, '<td valign="top">Comment only from a non-voting, non-member: Wow. Not sure why I keep coming back to this image. It has an odd combination of light and dark, and initially I want to see more highlights, but then I don''t... Compelling.</td>', 'Comment only from a non-voting, non-member: Wow. Not sure why I keep coming back to this image. It has an odd combination of light and dark, and initially I want to see more highlights, but then I don''t... Compelling.', '2010-07-06 23:33:44.000000', NULL, 1),
(6082849, 895465, 115814, '<td valign="top">Comment only from a non-voting, non-member: The bulk of submissions for this challenge seem bland and at times soul-less. This captures a spirit missing from most of the others.</td>', 'Comment only from a non-voting, non-member: The bulk of submissions for this challenge seem bland and at times soul-less. This captures a spirit missing from most of the others.', '2010-07-06 23:36:39.000000', NULL, 1),
