(6088464, 895419, 25313, '<td valign="top">the thumb appeared to be a statue...great posture and off camera gaze. 7</td>', 'the thumb appeared to be a statue...great posture and off camera gaze. 7', '2010-07-11 19:58:10.000000', NULL, 1),
(6088471, 895668, 25313, '<td valign="top">puzzled by the title...has an contrasting aura. there is trust in his eyes which conflicts with his attire. maybe  that is what is relative......6</td>', 'puzzled by the title...has an contrasting aura. there is trust in his eyes which conflicts with his attire. maybe  that is what is relative......6', '2010-07-11 20:03:52.000000', NULL, 1),
