(6088484, 895312, 25313, '<td valign="top">not only a candid but a snapshot taboot...i don''t care because the common statement it makes.6</td>', 'not only a candid but a snapshot taboot...i don''t care because the common statement it makes.6', '2010-07-11 20:20:21.000000', NULL, 1),
(6088485, 894595, 25313, '<td valign="top">it''s me but, i take some objection to photography of the homeless. by your title there is some hope here...the capture is outstanding...the story compelling.</td>', 'it''s me but, i take some objection to photography of the homeless. by your title there is some hope here...the capture is outstanding...the story compelling.', '2010-07-11 20:25:13.000000', NULL, 1),
(6088489, 895300, 25313, '<td valign="top">the first to view is his hair style...posture, background with it''s diagonal lines, and gaze works well with the bw treatment. 8</td>', 'the first to view is his hair style...posture, background with it''s diagonal lines, and gaze works well with the bw treatment. 8', '2010-07-11 20:34:05.000000', NULL, 1),
(6088493, 895537, 25313, '<td valign="top">sweet with no reluctance...harshness is somewhat distracting...that innocence captured makes up for it.</td>', 'sweet with no reluctance...harshness is somewhat distracting...that innocence captured makes up for it.', '2010-07-11 20:37:34.000000', NULL, 1),
(6088496, 895539, 25313, '<td valign="top">very coastal! he''s a photographer too. 6</td>', 'very coastal! he''s a photographer too. 6', '2010-07-11 20:38:56.000000', NULL, 1),
(6088497, 895518, 25313, '<td valign="top">i don''t see the negative for the title. possible "the man who saw everything"...love the tonality and facial gesture. 6</td>', 'i don''t see the negative for the title. possible "the man who saw everything"...love the tonality and facial gesture. 6', '2010-07-11 20:41:54.000000', NULL, 1),
(6088500, 895613, 25313, '<td valign="top">emulates the positives of youthfulness...nice tonality and dof...very clean composition.7</td>', 'emulates the positives of youthfulness...nice tonality and dof...very clean composition.7', '2010-07-11 20:44:03.000000', NULL, 1),
(6088502, 895625, 25313, '<td valign="top">in metropolis .</td>', 'in metropolis .', '2010-07-11 20:45:03.000000', NULL, 1),
