(6088525, 895484, 25313, '<td valign="top">this child could be a poster for the world...disturbing and provocative...i only wish i could see more hope in these eyes. 9</td>', 'this child could be a poster for the world...disturbing and provocative...i only wish i could see more hope in these eyes. 9', '2010-07-11 20:58:52.000000', NULL, 1),
