(6088534, 895459, 25313, '<td valign="top">i only wish that the sunglasses weren''t there...everything else is perfect perticularly the native american attire. 6</td>', 'i only wish that the sunglasses weren''t there...everything else is perfect perticularly the native american attire. 6', '2010-07-11 21:07:43.000000', NULL, 1),
