(6089296, 895578, 48546, '<td valign="top">Another great picture Shermy. Congrats on your top 10.</td>', 'Another great picture Shermy. Congrats on your top 10.', '2010-07-12 09:58:22.000000', NULL, 0),
(6089298, 895432, 82707, '<td valign="top">Congrats on the red!  Your subject is unique and compelling. Rule of thirds rules on this one, and I really love your background off to the right.  It totally compliments the model.  Great to see you back on the front page.</td>', 'Congrats on the red!  Your subject is unique and compelling. Rule of thirds rules on this one, and I really love your background off to the right.  It totally compliments the model.  Great to see you back on the front page.', '2010-07-12 10:01:43.000000', NULL, 0),
